('TRUE_FALSE'::question_type,'EASY'::level,'La chauve-souris est un mammifère.','The bat is a mammal.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,true::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Vrai : la chauve-souris allaite ses petits ; c''est le seul mammifère capable de vol actif.'::text,'True: bats nurse their young; they are the only mammals capable of true flight.'::text,2),
