('MCQ'::question_type,'MEDIUM'::level,'Quel est le plus grand oiseau vivant ?','What is the largest living bird?',ARRAY['Émeu','Condor des Andes','Albatros hurleur','Autruche']::text[],ARRAY['Emu','Andean condor','Wandering albatross','Ostrich']::text[],3::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'L''autruche d''Afrique peut dépasser 2,5 m et 150 kg.'::text,'The African ostrich can exceed 2.5 m and 150 kg.'::text,4),
('MCQ'::question_type,'MEDIUM'::level,'Comment appelle-t-on un animal qui se nourrit principalement de fruits ?','What do you call an animal that feeds mainly on fruit?',ARRAY['Granivore','Frugivore','Folivore','Insectivore']::text[],ARRAY['Granivore','Frugivore','Folivore','Insectivore']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Frugivore vient du latin frux (fruit) et vorare (dévorer).'::text,'Frugivore comes from Latin frux (fruit) and vorare (to devour).'::text,5),
('MCQ'::question_type,'MEDIUM'::level,'En combien de compartiments se divise l''estomac d''une vache ?','How many compartments does a cow''s stomach have?',ARRAY['1','2','3','4']::text[],ARRAY['1','2','3','4']::text[],3::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Panse, bonnet, feuillet et caillette : les 4 compartiments des ruminants.'::text,'Rumen, reticulum, omasum and abomasum: the 4 compartments of ruminants.'::text,6),
