('TRUE_FALSE'::question_type,'MEDIUM'::level,'Le koala est une espèce d''ours.','The koala is a species of bear.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : le koala est un marsupial, qui porte son petit dans une poche.'::text,'False: the koala is a marsupial that carries its young in a pouch.'::text,8),
('FREE_TEXT'::question_type,'MEDIUM'::level,'Comment s''appelle le processus par lequel les plantes fabriquent leur matière organique grâce à la lumière ?','What is the process by which plants make organic matter using light?',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'photosynthèse'::text,'photosynthesis'::text,ARRAY['photosynthèse','la photosynthèse','photosynthese']::text[],ARRAY['photosynthesis']::text[],'La photosynthèse transforme lumière, eau et CO2 en sucres et libère de l''oxygène.'::text,'Photosynthesis turns light, water and CO2 into sugars and releases oxygen.'::text,9),
('MCQ'::question_type,'EXPERT'::level,'L''axolotl, qui reste toute sa vie à l''état larvaire, est une espèce de…','The axolotl, which keeps its larval form for life, is a species of…',ARRAY['Poisson','Salamandre','Grenouille','Lézard']::text[],ARRAY['Fish','Salamander','Frog','Lizard']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'L''axolotl (Ambystoma mexicanum) est une salamandre néoténique du Mexique.'::text,'The axolotl (Ambystoma mexicanum) is a neotenic salamander from Mexico.'::text,10),
('MCQ'::question_type,'EXPERT'::level,'Chez l''ornithorynque mâle, où se trouve le venin ?','Where is the venom located in the male platypus?',ARRAY['Dans le bec','Dans la queue','Dans les éperons des pattes arrière','Dans les dents']::text[],ARRAY['In the bill','In the tail','In the spurs on its hind legs','In its teeth']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Le mâle possède un éperon venimeux sur chaque patte arrière.'::text,'The male has a venomous spur on each hind leg.'::text,11),
('MCQ'::question_type,'EXPERT'::level,'Quelle plante produit la plus grande fleur individuelle du monde ?','Which plant produces the largest single flower in the world?',ARRAY['Nénuphar géant d''Amazonie','Lotus sacré','Tournesol','Rafflesia arnoldii']::text[],ARRAY['Giant Amazon water lily','Sacred lotus','Sunflower','Rafflesia arnoldii']::text[],3::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'La fleur de Rafflesia arnoldii peut atteindre environ 1 m de diamètre.'::text,'The Rafflesia arnoldii flower can reach about 1 m across.'::text,12),
('MCQ'::question_type,'EXPERT'::level,'Quelle espèce de manchot vit à l''état sauvage jusqu''au nord de l''équateur ?','Which penguin species lives in the wild as far as north of the equator?',ARRAY['Manchot empereur','Manchot des Galápagos','Manchot de Humboldt','Manchot du Cap']::text[],ARRAY['Emperor penguin','Galápagos penguin','Humboldt penguin','African penguin']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Le manchot des Galápagos est le seul manchot présent au nord de l''équateur (île Isabela).'::text,'The Galápagos penguin is the only penguin found north of the equator (Isabela Island).'::text,13),
('TRUE_FALSE'::question_type,'EXPERT'::level,'Les plus proches parents vivants de l''hippopotame sont les cétacés (baleines et dauphins).','The hippopotamus''s closest living relatives are the cetaceans (whales and dolphins).',ARRAY[]::text[],ARRAY[]::text[],NULL::int,true::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Vrai : les études génétiques placent hippopotames et cétacés dans un même groupe, les Whippomorpha.'::text,'True: genetic studies group hippos and cetaceans together as Whippomorpha.'::text,14),
