('TRUE_FALSE'::question_type,'MEDIUM'::level,'Le Luxembourg a une frontière avec les Pays-Bas.','Luxembourg shares a border with the Netherlands.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : ses voisins sont la Belgique, la France et l''Allemagne.'::text,'False: its neighbours are Belgium, France and Germany.'::text,5),
('FREE_TEXT'::question_type,'MEDIUM'::level,'Quel détroit sépare l''Espagne du Maroc ?','Which strait separates Spain from Morocco?',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Gibraltar'::text,'Gibraltar'::text,ARRAY['Gibraltar','détroit de Gibraltar','le détroit de Gibraltar']::text[],ARRAY['Gibraltar','Strait of Gibraltar']::text[],'Le détroit de Gibraltar relie l''Atlantique à la Méditerranée.'::text,'The Strait of Gibraltar links the Atlantic to the Mediterranean.'::text,6),
