('MCQ'::question_type,'EASY'::level,'Quelle célèbre tapisserie raconte la conquête de l''Angleterre par Guillaume le Conquérant en 1066 ?','Which famous tapestry tells the story of William the Conqueror''s conquest of England in 1066?',ARRAY['La Dame à la licorne','La tenture de l''Apocalypse','La tapisserie de Bayeux','La tapisserie d''Aubusson']::text[],ARRAY['The Lady and the Unicorn','The Apocalypse Tapestry','The Bayeux Tapestry','The Aubusson Tapestry']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'La tapisserie de Bayeux, brodée au XIe siècle, relate la conquête normande de l''Angleterre.'::text,'The Bayeux Tapestry, embroidered in the 11th century, depicts the Norman conquest of England.'::text,1),
('TRUE_FALSE'::question_type,'EASY'::level,'Le général de Gaulle a lancé l''appel du 18 juin 1940 depuis Alger.','General de Gaulle made his Appeal of 18 June 1940 from Algiers.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : l''appel du 18 juin a été lancé depuis Londres, sur les ondes de la BBC.'::text,'False: the Appeal of 18 June was broadcast from London on the BBC.'::text,2),
