('MCQ'::question_type,'MEDIUM'::level,'Quel roi a signé l''édit de Nantes en 1598 ?','Which king signed the Edict of Nantes in 1598?',ARRAY['François Ier','Henri III','Henri IV','Louis XIII']::text[],ARRAY['Francis I','Henry III','Henry IV','Louis XIII']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Henri IV signe l''édit de Nantes en 1598 pour mettre fin aux guerres de Religion.'::text,'Henry IV signed the Edict of Nantes in 1598 to end the Wars of Religion.'::text,4),
('MCQ'::question_type,'MEDIUM'::level,'En quelle année les Françaises ont-elles voté pour la première fois ?','In what year did French women vote for the first time?',ARRAY['1936','1945','1958','1968']::text[],ARRAY['1936','1945','1958','1968']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Les Françaises votent pour la première fois aux municipales du 29 avril 1945.'::text,'French women first voted in the municipal elections of 29 April 1945.'::text,5),
('TRUE_FALSE'::question_type,'MEDIUM'::level,'La bataille d''Alésia, en 52 av. J.-C., fut une victoire de Vercingétorix.','The Battle of Alesia in 52 BC was a victory for Vercingetorix.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : Jules César remporte Alésia et Vercingétorix se rend.'::text,'False: Julius Caesar won at Alesia and Vercingetorix surrendered.'::text,6),
