('MCQ'::question_type,'MEDIUM'::level,'Quel chanteur a interprété « La Bohème » en 1965 ?','Which singer performed "La Bohème" in 1965?',ARRAY['Gilbert Bécaud','Serge Gainsbourg','Michel Sardou','Charles Aznavour']::text[],ARRAY['Gilbert Bécaud','Serge Gainsbourg','Michel Sardou','Charles Aznavour']::text[],3::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'« La Bohème » est l''un des plus grands succès de Charles Aznavour.'::text,'"La Bohème" is one of Charles Aznavour''s biggest hits.'::text,20),
('TRUE_FALSE'::question_type,'MEDIUM'::level,'Les Rolling Stones se sont formés avant les Beatles.','The Rolling Stones formed before the Beatles.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Les Beatles se forment en 1960, les Rolling Stones en 1962.'::text,'The Beatles formed in 1960, the Rolling Stones in 1962.'::text,21),
('MCQ'::question_type,'EXPERT'::level,'Quel était le vrai nom de famille de Serge Gainsbourg ?','What was Serge Gainsbourg''s real surname?',ARRAY['Gainsberg','Ginsburg','Goldberg','Grünberg']::text[],ARRAY['Gainsberg','Ginsburg','Goldberg','Grünberg']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Serge Gainsbourg est né Lucien Ginsburg (parfois écrit Ginzburg) en 1928.'::text,'Serge Gainsbourg was born Lucien Ginsburg (sometimes spelled Ginzburg) in 1928.'::text,22),
('MCQ'::question_type,'EXPERT'::level,'Quel groupe a enregistré l''album « Pet Sounds » en 1966 ?','Which band recorded the album "Pet Sounds" in 1966?',ARRAY['The Byrds','The Kinks','The Beach Boys','The Doors']::text[],ARRAY['The Byrds','The Kinks','The Beach Boys','The Doors']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'« Pet Sounds » des Beach Boys, largement conçu par Brian Wilson, est sorti en 1966.'::text,'The Beach Boys'' "Pet Sounds", largely crafted by Brian Wilson, came out in 1966.'::text,23),
('FREE_TEXT'::question_type,'EXPERT'::level,'Quel est le prénom de Ravel, compositeur du « Boléro » ?','What was the first name of Ravel, composer of "Boléro"?',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Maurice'::text,'Maurice'::text,ARRAY['Maurice']::text[],ARRAY['Maurice']::text[],'Maurice Ravel a composé le « Boléro » en 1928.'::text,'Maurice Ravel composed "Boléro" in 1928.'::text,24),
('TRUE_FALSE'::question_type,'EXPERT'::level,'La chanson « Hallelujah » a été écrite par Jeff Buckley.','The song "Hallelujah" was written by Jeff Buckley.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'« Hallelujah » a été écrite par Leonard Cohen (album « Various Positions », 1984) ; Jeff Buckley en a fait une reprise célèbre.'::text,'"Hallelujah" was written by Leonard Cohen (album "Various Positions", 1984); Jeff Buckley recorded a famous cover.'::text,25),
('MCQ'::question_type,'EXPERT'::level,'Quelle chanteuse a remporté l''Eurovision 1977 pour la France avec « L''oiseau et l''enfant » ?','Which singer won Eurovision 1977 for France with "L''oiseau et l''enfant"?',ARRAY['Marie Myriam','Frida Boccara','Isabelle Aubret','Patricia Kaas']::text[],ARRAY['Marie Myriam','Frida Boccara','Isabelle Aubret','Patricia Kaas']::text[],0::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Marie Myriam a gagné l''Eurovision 1977 à Londres avec « L''oiseau et l''enfant ».'::text,'Marie Myriam won Eurovision 1977 in London with "L''oiseau et l''enfant".'::text,26),
('MCQ'::question_type,'EXPERT'::level,'Quel saxophoniste de jazz était surnommé « Bird » ?','Which jazz saxophonist was nicknamed "Bird"?',ARRAY['Sonny Rollins','Charlie Parker','Stan Getz','John Coltrane']::text[],ARRAY['Sonny Rollins','Charlie Parker','Stan Getz','John Coltrane']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Charlie Parker, pionnier du bebop, était surnommé « Bird » ou « Yardbird ».'::text,'Charlie Parker, a bebop pioneer, was nicknamed "Bird" or "Yardbird".'::text,27),
('FREE_TEXT'::question_type,'EXPERT'::level,'Dans quelle ville anglaise le groupe Oasis s''est-il formé ?','In which English city was the band Oasis formed?',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Manchester'::text,'Manchester'::text,ARRAY['Manchester']::text[],ARRAY['Manchester']::text[],'Oasis s''est formé à Manchester en 1991 autour des frères Gallagher.'::text,'Oasis formed in Manchester in 1991 around the Gallagher brothers.'::text,28),
('TRUE_FALSE'::question_type,'EXPERT'::level,'David Bowie a sorti l''album « Blackstar » deux jours avant sa mort.','David Bowie released the album "Blackstar" two days before his death.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,true::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'« Blackstar » est sorti le 8 janvier 2016 et Bowie est mort le 10 janvier 2016.'::text,'"Blackstar" was released on 8 January 2016 and Bowie died on 10 January 2016.'::text,29)
