('MCQ'::question_type,'EASY'::level,'Quel héros grec a eu l''idée du cheval de Troie ?','Which Greek hero came up with the idea of the Trojan Horse?',ARRAY['Achille','Hector','Ulysse','Pâris']::text[],ARRAY['Achilles','Hector','Odysseus','Paris']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Ulysse (Odysseus) est le concepteur de la ruse du cheval de bois selon l''Odyssée et l''Énéide.'::text,'Odysseus devised the wooden horse ruse according to the Odyssey and the Aeneid.'::text,1),
('TRUE_FALSE'::question_type,'EASY'::level,'Poséidon est le dieu grec des Enfers.','Poseidon is the Greek god of the Underworld.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : Poséidon est le dieu de la mer ; les Enfers sont le domaine d''Hadès.'::text,'False: Poseidon is god of the sea; the Underworld belongs to Hades.'::text,2),
('FREE_TEXT'::question_type,'EASY'::level,'Le Titan condamné par Zeus à porter le ciel sur ses épaules s''appelle ___.','The Titan condemned by Zeus to hold up the sky on his shoulders is called ___.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Atlas'::text,'Atlas'::text,ARRAY['atlas']::text[],ARRAY['atlas']::text[],'Après la Titanomachie, Zeus condamne Atlas à soutenir la voûte céleste.'::text,'After the Titanomachy, Zeus condemned Atlas to hold up the heavens.'::text,3),
('MCQ'::question_type,'MEDIUM'::level,'Quelle déesse grecque est née, tout armée, de la tête de Zeus ?','Which Greek goddess was born, fully armed, from Zeus''s head?',ARRAY['Athéna','Artémis','Héra','Déméter']::text[],ARRAY['Athena','Artemis','Hera','Demeter']::text[],0::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Athéna jaillit du crâne de Zeus, après que celui-ci eut avalé Métis enceinte.'::text,'Athena sprang from Zeus''s head after he swallowed the pregnant Metis.'::text,4),
('MCQ'::question_type,'MEDIUM'::level,'Quelle déesse romaine correspond à Héra, l''épouse de Zeus ?','Which Roman goddess corresponds to Hera, Zeus''s wife?',ARRAY['Vénus','Minerve','Diane','Junon']::text[],ARRAY['Venus','Minerva','Diana','Juno']::text[],3::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Junon, épouse de Jupiter, a été assimilée à l''Héra grecque.'::text,'Juno, wife of Jupiter, was identified with the Greek Hera.'::text,5),
('MCQ'::question_type,'MEDIUM'::level,'Quelle créature Œdipe a-t-il vaincue en résolvant son énigme ?','Which creature did Oedipus defeat by solving its riddle?',ARRAY['La Chimère','Le Sphinx','La Méduse','L''Hydre']::text[],ARRAY['The Chimera','The Sphinx','Medusa','The Hydra']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Œdipe répond « l''homme » à l''énigme du Sphinx de Thèbes.'::text,'Oedipus answered "man" to the riddle of the Sphinx of Thebes.'::text,6),
('MCQ'::question_type,'MEDIUM'::level,'Dans la mythologie égyptienne, quel dieu est assassiné par son frère Seth ?','In Egyptian mythology, which god is murdered by his brother Set?',ARRAY['Anubis','Ra','Osiris','Thot']::text[],ARRAY['Anubis','Ra','Osiris','Thoth']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Seth tue et démembre Osiris ; Isis rassemble ensuite les morceaux de son corps.'::text,'Set kills and dismembers Osiris; Isis then gathers the pieces of his body.'::text,7),
('TRUE_FALSE'::question_type,'MEDIUM'::level,'Dans la mythologie nordique, Loki est le frère de Thor.','In Norse mythology, Loki is Thor''s brother.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : Loki est le fils de Fárbauti et Laufey ; le lien fraternel avec Thor vient des films Marvel.'::text,'False: Loki is the son of Fárbauti and Laufey; the brotherhood with Thor comes from the Marvel films.'::text,8),
('FREE_TEXT'::question_type,'MEDIUM'::level,'Le Titan qui vola le feu aux dieux pour le donner aux hommes s''appelle ___.','The Titan who stole fire from the gods to give it to humans is called ___.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Prométhée'::text,'Prometheus'::text,ARRAY['prométhée','promethee','prometheus']::text[],ARRAY['prometheus']::text[],'Pour ce vol, Prométhée fut enchaîné sur le Caucase, un aigle lui dévorant le foie.'::text,'For this theft, Prometheus was chained to the Caucasus while an eagle ate his liver.'::text,9),
('MCQ'::question_type,'EXPERT'::level,'Comment s''appelle le cheval à huit pattes d''Odin ?','What is the name of Odin''s eight-legged horse?',ARRAY['Gullinbursti','Hugin','Fenrir','Sleipnir']::text[],ARRAY['Gullinbursti','Huginn','Fenrir','Sleipnir']::text[],3::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Sleipnir, né de Loki et de l''étalon Svaðilfari, est la monture d''Odin.'::text,'Sleipnir, born of Loki and the stallion Svaðilfari, is Odin''s steed.'::text,10),
('MCQ'::question_type,'EXPERT'::level,'Quel fleuve des Enfers grecs fait oublier leur vie passée aux âmes qui y boivent ?','Which river of the Greek Underworld makes souls who drink from it forget their past life?',ARRAY['Le Styx','Le Léthé','L''Achéron','Le Cocyte']::text[],ARRAY['The Styx','The Lethe','The Acheron','The Cocytus']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Léthé signifie « oubli » en grec ancien.'::text,'Lethe means "forgetfulness" in ancient Greek.'::text,11),
('MCQ'::question_type,'EXPERT'::level,'Quelle Muse préside à l''Histoire ?','Which Muse presides over History?',ARRAY['Clio','Calliope','Thalie','Uranie']::text[],ARRAY['Clio','Calliope','Thalia','Urania']::text[],0::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Clio est la muse de l''Histoire ; Calliope celle de la poésie épique.'::text,'Clio is the Muse of History; Calliope that of epic poetry.'::text,12),
('MCQ'::question_type,'EXPERT'::level,'Dans la mythologie nordique, quelle déesse aux cheveux d''or est l''épouse de Thor ?','In Norse mythology, which golden-haired goddess is Thor''s wife?',ARRAY['Frigg','Freyja','Sif','Idunn']::text[],ARRAY['Frigg','Freyja','Sif','Idunn']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Loki coupa les cheveux de Sif, remplacés par une chevelure d''or forgée par les nains.'::text,'Loki cut Sif''s hair, which was replaced by golden hair forged by the dwarves.'::text,13),
('TRUE_FALSE'::question_type,'EXPERT'::level,'Dans la mythologie égyptienne, Horus est le fils de Seth.','In Egyptian mythology, Horus is the son of Set.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : Horus est le fils d''Isis et d''Osiris, et le rival de Seth.'::text,'False: Horus is the son of Isis and Osiris, and Set''s rival.'::text,14),
('FREE_TEXT'::question_type,'EXPERT'::level,'Le dieu égyptien de l''écriture, à tête d''ibis, s''appelle ___.','The ibis-headed Egyptian god of writing is called ___.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Thot'::text,'Thoth'::text,ARRAY['thot','thoth','djehuty']::text[],ARRAY['thoth','thot','djehuty']::text[],'Thot, dieu du savoir et patron des scribes, est souvent représenté avec une tête d''ibis.'::text,'Thoth, god of knowledge and patron of scribes, is often depicted with an ibis head.'::text,15)
