('MCQ'::question_type,'EASY'::level,'Quel général carthaginois a traversé les Alpes avec des éléphants ?','Which Carthaginian general crossed the Alps with elephants?',ARRAY['Scipion','Hannibal','Spartacus','Hamilcar']::text[],ARRAY['Scipio','Hannibal','Spartacus','Hamilcar']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Hannibal envahit l''Italie en 218 av. J.-C. en franchissant les Alpes avec ses éléphants de guerre.'::text,'Hannibal invaded Italy in 218 BC by crossing the Alps with his war elephants.'::text,1),
('TRUE_FALSE'::question_type,'EASY'::level,'Abraham Lincoln a été assassiné dans un théâtre.','Abraham Lincoln was assassinated in a theatre.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,true::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Vrai : il a été abattu le 14 avril 1865 au Ford''s Theatre de Washington.'::text,'True: he was shot on 14 April 1865 at Ford''s Theatre in Washington.'::text,2),
('FREE_TEXT'::question_type,'EASY'::level,'La physicienne et chimiste, deux fois prix Nobel (1903 et 1911), s''appelle Marie ___.','The physicist and chemist who won two Nobel Prizes (1903 and 1911) is Marie ___.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Curie'::text,'Curie'::text,ARRAY['curie','sklodowska-curie','skłodowska-curie']::text[],ARRAY['curie','sklodowska-curie','skłodowska-curie']::text[],'Marie Curie reçoit le Nobel de physique en 1903 et celui de chimie en 1911.'::text,'Marie Curie won the Nobel Prize in Physics in 1903 and in Chemistry in 1911.'::text,3),
('MCQ'::question_type,'MEDIUM'::level,'En quelle année Charlemagne a-t-il été couronné empereur à Rome ?','In what year was Charlemagne crowned emperor in Rome?',ARRAY['732','843','800','987']::text[],ARRAY['732','843','800','987']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Le pape Léon III le couronne à Saint-Pierre le jour de Noël 800.'::text,'Pope Leo III crowned him at St Peter''s on Christmas Day 800.'::text,4),
('MCQ'::question_type,'MEDIUM'::level,'Quel président américain était en fonction lors de la crise des missiles de Cuba en 1962 ?','Which US president was in office during the 1962 Cuban Missile Crisis?',ARRAY['John F. Kennedy','Dwight Eisenhower','Richard Nixon','Lyndon Johnson']::text[],ARRAY['John F. Kennedy','Dwight Eisenhower','Richard Nixon','Lyndon Johnson']::text[],0::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'En octobre 1962, Kennedy impose un blocus naval à Cuba face aux missiles soviétiques.'::text,'In October 1962, Kennedy imposed a naval blockade on Cuba over Soviet missiles.'::text,5),
('MCQ'::question_type,'MEDIUM'::level,'Quel empereur romain a fait construire un mur en travers du nord de l''Angleterre ?','Which Roman emperor had a wall built across northern England?',ARRAY['Trajan','Néron','Auguste','Hadrien']::text[],ARRAY['Trajan','Nero','Augustus','Hadrian']::text[],3::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Le mur d''Hadrien est commencé en 122 apr. J.-C. sous son règne.'::text,'Hadrian''s Wall was begun in AD 122 during his reign.'::text,6),
('MCQ'::question_type,'MEDIUM'::level,'Quel marchand vénitien a raconté son voyage en Chine dans « Le Devisement du monde » ?','Which Venetian merchant described his journey to China in "The Travels" (Book of the Marvels of the World)?',ARRAY['Vasco de Gama','Marco Polo','Ibn Battuta','Amerigo Vespucci']::text[],ARRAY['Vasco da Gama','Marco Polo','Ibn Battuta','Amerigo Vespucci']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Marco Polo dicta ses récits en prison à Rustichello de Pise.'::text,'Marco Polo dictated his stories in prison to Rustichello da Pisa.'::text,7),
('TRUE_FALSE'::question_type,'MEDIUM'::level,'Jules César a été le premier empereur romain.','Julius Caesar was the first Roman emperor.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : César fut dictateur ; le premier empereur est Auguste, en 27 av. J.-C.'::text,'False: Caesar was dictator; the first emperor was Augustus, in 27 BC.'::text,8),
('FREE_TEXT'::question_type,'MEDIUM'::level,'Le navigateur portugais qui dirigea la première expédition autour du monde (1519-1522), mort en route, s''appelle Fernand de ___.','The Portuguese navigator who led the first expedition around the world (1519-1522) and died on the way is Ferdinand ___.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Magellan'::text,'Magellan'::text,ARRAY['magellan','magalhães','magalhaes']::text[],ARRAY['magellan','magalhães','magalhaes']::text[],'Magellan meurt aux Philippines en 1521 ; Elcano ramène la Victoria en Espagne.'::text,'Magellan died in the Philippines in 1521; Elcano brought the Victoria back to Spain.'::text,9),
('MCQ'::question_type,'EXPERT'::level,'Qui est devenu le premier empereur de la Chine unifiée en 221 av. J.-C. ?','Who became the first emperor of unified China in 221 BC?',ARRAY['Kubilaï Khan','Liu Bang','Qin Shi Huang','Wu Zetian']::text[],ARRAY['Kublai Khan','Liu Bang','Qin Shi Huang','Wu Zetian']::text[],2::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Qin Shi Huang unifie la Chine en 221 av. J.-C. ; il est célèbre pour son armée de terre cuite.'::text,'Qin Shi Huang unified China in 221 BC; he is famous for his Terracotta Army.'::text,10),
('MCQ'::question_type,'EXPERT'::level,'Quel sultan ottoman a pris Constantinople en 1453 ?','Which Ottoman sultan captured Constantinople in 1453?',ARRAY['Soliman le Magnifique','Sélim Ier','Bayezid Ier','Mehmed II']::text[],ARRAY['Suleiman the Magnificent','Selim I','Bayezid I','Mehmed II']::text[],3::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Mehmed II, dit « le Conquérant », fait de la ville la capitale ottomane.'::text,'Mehmed II, "the Conqueror", made the city the Ottoman capital.'::text,11),
('MCQ'::question_type,'EXPERT'::level,'Quelle souveraine d''Égypte se faisait représenter en pharaon, avec la barbe postiche ?','Which female ruler of Egypt had herself depicted as a pharaoh, wearing the false beard?',ARRAY['Hatchepsout','Néfertiti','Cléopâtre VII','Néfertari']::text[],ARRAY['Hatshepsut','Nefertiti','Cleopatra VII','Nefertari']::text[],0::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Hatchepsout (XVIIIe dynastie) adopte tous les attributs royaux masculins, dont la barbe postiche.'::text,'Hatshepsut (18th Dynasty) adopted all the male royal regalia, including the false beard.'::text,12),
('MCQ'::question_type,'EXPERT'::level,'Quel roi de Macédoine était le père d''Alexandre le Grand ?','Which king of Macedon was the father of Alexander the Great?',ARRAY['Darius III','Philippe II','Léonidas','Périclès']::text[],ARRAY['Darius III','Philip II','Leonidas','Pericles']::text[],1::int,NULL::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Philippe II est assassiné en 336 av. J.-C. ; son fils Alexandre lui succède.'::text,'Philip II was assassinated in 336 BC; his son Alexander succeeded him.'::text,13),
('TRUE_FALSE'::question_type,'EXPERT'::level,'Lors de son premier voyage en 1492, Christophe Colomb naviguait pour le compte du roi du Portugal.','On his first voyage in 1492, Christopher Columbus sailed on behalf of the King of Portugal.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,false::boolean,NULL::text,NULL::text,ARRAY[]::text[],ARRAY[]::text[],'Faux : il naviguait pour les Rois catholiques d''Espagne, Isabelle de Castille et Ferdinand d''Aragon.'::text,'False: he sailed for the Catholic Monarchs of Spain, Isabella of Castile and Ferdinand of Aragon.'::text,14),
('FREE_TEXT'::question_type,'EXPERT'::level,'Le dirigeant qui a proclamé l''indépendance du Viêt Nam en 1945 s''appelle ___.','The leader who proclaimed Vietnam''s independence in 1945 is ___.',ARRAY[]::text[],ARRAY[]::text[],NULL::int,NULL::boolean,'Hô Chi Minh'::text,'Ho Chi Minh'::text,ARRAY['hô chi minh','ho chi minh','ho chi-minh','hồ chí minh','ho-chi-minh']::text[],ARRAY['ho chi minh','ho chi-minh','hồ chí minh','ho-chi-minh']::text[],'Le 2 septembre 1945, Hô Chi Minh proclame la République démocratique du Viêt Nam à Hanoï.'::text,'On 2 September 1945, Ho Chi Minh proclaimed the Democratic Republic of Vietnam in Hanoi.'::text,15)
